record.field:
# =====================================================================
# Customer set or changed -> use the customer's B2B warehouse.
# Automation "Warehouse b2b" (sale.order, on partner_id change).
# =====================================================================

for order in records:
    warehouse = order.partner_id.x_studio_warehouse_id
    if not warehouse:
        continue
    if warehouse.company_id != order.company_id:
        continue        # a warehouse of another company would block the save
    if order.warehouse_id != warehouse:
        order.write({'warehouse_id': warehouse.id})

# Available variables: # - env: environment on which the action is triggered # - model: model of the record on which the action is triggered; is a void recordset # - record: record on which the action is triggered; may be void # - records: recordset of all records on which the action is triggered in multi-mode; may be void # - time, datetime, dateutil, timezone: useful Python libraries # - float_compare: utility function to compare floats based on specific precision # - log: log(message, level='info'): logging function to record debug information in ir.logging table # - _logger: _logger.info(message): logger to emit messages in server logs # - UserError: exception class for raising user-facing warning messages # - Command: x2many commands namespace # To return an action, assign: action = {...}
# Buscar pedidos de venta con la etiqueta ID=2 y estado 'draft' orders = env['sale.order'].search([ ('tag_ids', 'in', [2]), ('state', '=', 'sale') ])
for order in orders: # Duplicar el pedido (Odoo generará un nuevo name automáticamente) new_order = order.copy()
# Asegurar que el nuevo pedido quede como Presupuesto y quitar etiqueta new_order.write({ 'state': 'draft', 'tag_ids': [(3, 2)] })
# Agregar mensaje en el chatter del duplicado new_order.message_post(body=f"Este pedido fue generado automáticamente como duplicado de {order.name}.")

